function filterBar(){const months=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];return `<div class="al-toolbar"><label>Laporan<select data-report><option value="">Pilih laporan…</option>${reports.map(([id,label])=>`<option value="${id}" ${activeReport===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Tahun<select data-period-year><option value="">Semua tahun</option>${periodYears.map(year=>`<option value="${year}" ${periodYear===year?'selected':''}>${year}</option>`).join('')}</select></label><label>Bulan<select data-period-month ${periodYear?'':'disabled'}><option value="">Semua bulan</option>${months.map((name,index)=>`<option value="${index+1}" ${String(periodMonth)===String(index+1)?'selected':''}>${name}</option>`).join('')}</select></label><label>Dari<input type="date" data-start value="${esc(start)}"></label><label>Sampai<input type="date" data-end value="${esc(end)}"></label><button class="al-btn" data-filter>Terapkan</button><span class="al-status">Data historis hanya-baca</span></div>`}
