function pageControls(page,rerender){if(!page)return '';const limit=page.limit||200,totalPages=Math.max(1,Math.ceil((page.total||0)/limit)),current=Math.min(totalPages,Math.floor((page.offset||0)/limit)+1),first=page.total?`${page.offset+1}–${Math.min(page.offset+limit,page.total)} dari ${page.total.toLocaleString('id-ID')} baris`:'0 baris';return `<div class="al-total al-pagination"><span>${first} · Halaman ${current} dari ${totalPages}</span><span><button class="al-btn" data-page-first ${current>1?'':'disabled'}>« Pertama</button> <button class="al-btn" data-page-prev ${current>1?'':'disabled'}>← Sebelumnya</button> <label class="al-page-jump">Ke halaman <input type="number" min="1" max="${totalPages}" value="${current}" data-page-go-input></label> <button class="al-btn" data-page-go>Go</button> <button class="al-btn" data-page-next ${current<totalPages?'':'disabled'}>Berikutnya →</button> <button class="al-btn" data-page-last ${current<totalPages?'':'disabled'}>Terakhir »</button></span></div>`;}
function wirePageControls(root,page,rerender){const limit=page.limit||200,totalPages=Math.max(1,Math.ceil((page.total||0)/limit)),go=number=>{const target=Math.max(1,Math.min(totalPages,Number(number)||1));reportOffsets.set(activeReport,(target-1)*limit);rerender();};q('[data-page-first]',root)?.addEventListener('click',()=>go(1));q('[data-page-prev]',root)?.addEventListener('click',()=>go(Math.floor((page.offset||0)/limit)));q('[data-page-next]',root)?.addEventListener('click',()=>go(Math.floor((page.offset||0)/limit)+2));q('[data-page-last]',root)?.addEventListener('click',()=>go(totalPages));q('[data-page-go]',root)?.addEventListener('click',()=>go(q('[data-page-go-input]',root)?.value));q('[data-page-go-input]',root)?.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();go(event.currentTarget.value);}});}
function wirePeriodFilters(root,apply){const year=q('[data-period-year]',root),month=q('[data-period-month]',root),report=q('[data-report]',root);if(year&&month)year.onchange=()=>{month.disabled=!year.value;if(!year.value)month.value='';};report.onchange=()=>{activeReport=report.value;loadedReportTabs.delete(activeReport);reportOffsets.set(activeReport,0);deferredReportView();};q('[data-filter]',root).onclick=()=>{activeReport=report.value;if(!activeReport)return deferredReportView();readDates(root);loadedReportTabs.add(activeReport);reportOffsets.set(activeReport,0);apply();};const exportButton=document.createElement('button');exportButton.type='button';exportButton.className='al-btn';exportButton.dataset.accountingExport='';exportButton.textContent='↓ Export Excel';exportButton.disabled=!(activeReport&&activeReport!=='closing'&&loadedReportTabs.has(activeReport));q('.al-status',root)?.insertAdjacentElement('afterend',exportButton);exportButton.onclick=async()=>{if(exportButton.disabled)return;const params=new URLSearchParams({report:activeReport,start,end});if(activeReport==='ledger')params.set('account_code',selectedAccount);if(activeReport==='stock')params.set('item_code',stockItem);const original=exportButton.textContent;exportButton.disabled=true;exportButton.textContent='Menyiapkan...';try{const response=await fetch(`/api/accounting-lite/export.xlsx?${params}`);if(!response.ok){let message='Ekspor gagal dibuat.';try{message=(await response.json()).error||message;}catch{}throw new Error(message);}const blob=await response.blob(),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`accounting-lite-${activeReport}-${start||'semua'}-${end||'semua'}.xlsx`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}catch(error){alert(error.message||'Ekspor gagal dibuat.');}finally{exportButton.disabled=!(activeReport&&activeReport!=='closing'&&loadedReportTabs.has(activeReport));exportButton.textContent=original;}};setTimeout(syncStickyLayers,0);}
async function journalView(){const content=q('#alContent'),offset=reportOffsets.get('journals')||0;content.innerHTML=`${filterBar()}<div class="al-card"><div class="al-empty">Memuat jurnal…</div></div>`;wirePeriodFilters(content,journalView);try{const d=await api(`/api/accounting-lite/journals?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}&limit=200&offset=${offset}`),rows=d.records||[];content.querySelector('.al-card').innerHTML=`<div class="al-table-wrap"><table class="al-table"><thead><tr><th>Tanggal</th><th>No Bukti</th><th>Uraian</th><th>Jenis</th><th class="number">Debit</th><th class="number">Kredit</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr class="clickable" data-journal="${x.id}"><td>${date(x.transaction_date)}</td><td><b>${esc(x.voucher_number)}</b><br><span class="al-badge ${x.source==='legacy'?'locked':'manual'}">${x.source==='legacy'?'Historis':'Baru'}</span></td><td>${esc(x.description||'—')}</td><td>${esc(x.transaction_type||'—')}</td><td class="number">${money(x.debit_total)}</td><td class="number">${money(x.credit_total)}</td><td><button class="al-btn" data-open="${x.id}">Buka</button></td></tr>`).join('')||'<tr><td colspan="7" class="al-empty">Tidak ada jurnal pada periode ini.</td></tr>'}</tbody></table></div>${pageControls(d.page,journalView)}`;qa('[data-open]',content).forEach(b=>b.onclick=e=>{e.stopPropagation();openJournal(b.dataset.open)});qa('tr[data-journal]',content).forEach(r=>r.onclick=()=>openJournal(r.dataset.journal));wirePageControls(content,d.page,journalView);}catch(e){content.innerHTML=`<div class="al-empty">${esc(e.message)}</div>`}}
