function rupiahParts(value){const text=String(value??'').replace(/[^0-9,.]/g,''),comma=text.lastIndexOf(',');if(!text)return {empty:true,integer:'',fraction:''};let whole=text,fraction='';if(comma>=0){whole=text.slice(0,comma);fraction=text.slice(comma+1);}else{const dots=(text.match(/\./g)||[]).length,lastDot=text.lastIndexOf('.'),tail=lastDot>=0?text.slice(lastDot+1):'';if(dots===1&&tail.length>0&&tail.length<=2){whole=text.slice(0,lastDot);fraction=tail;}}const integer=whole.replace(/\D/g,''),decimal=fraction.replace(/\D/g,'').slice(0,2);if(!integer&&!decimal)return {empty:true,integer:'',fraction:''};return {empty:false,integer:integer||'0',fraction:decimal};}
