function accountCodeTyping(value,segments){const digits=String(value||'').replace(/\D/g,'').slice(0,segments.reduce((sum,length)=>sum+length,0));let cursor=0,output=[];for(let index=0;index<segments.length&&cursor<digits.length;index++){const part=digits.slice(cursor,cursor+segments[index]);output.push(part);cursor+=part.length;}const complete=output.length<segments.length&&output.at(-1)?.length===segments[output.length-1];return output.join('.')+(complete?'.':'');}
function accountCodeCanonicalDraft(value,segments){const digits=String(value||'').replace(/\D/g,''),total=segments.reduce((sum,length)=>sum+length,0);if(!digits)throw new Error('Kode rekening wajib diisi.');if(digits.length!==total)throw new Error(`Kode rekening harus berisi ${total} digit.`);let cursor=0;return segments.map(length=>{const part=digits.slice(cursor,cursor+length);cursor+=length;return part;}).join('.');}
