function accountMasterDescendants(accountCode){const children=new Map();accounts.forEach(account=>{const parent=account.parent_code||'';if(!children.has(parent))children.set(parent,[]);children.get(parent).push(account.account_code);});const result=new Set(),queue=[accountCode];while(queue.length){(children.get(queue.shift())||[]).forEach(child=>{if(result.has(child))return;result.add(child);queue.push(child);});}return result;}
