wireNamedAccountPicker=function(wrapper){
  if(wrapper.dataset.wired)return;wrapper.dataset.wired='1';
  const target=wrapper.dataset.accountTarget,postingOnly=wrapper.dataset.postingOnly==='1',search=q('[data-account-search]',wrapper),hidden=q(`[name="${target}"]`,wrapper),results=q('[data-account-results]',wrapper),clear=q('[data-account-clear]',wrapper);let matches=[],active=-1;
  const choose=account=>{hidden.value=account.account_code;search.value=accountPickerLabel(account);results.hidden=true;clear.hidden=false;hidden.dispatchEvent(new Event('change',{bubbles:true}));};
  const draw=()=>{const query=search.value.trim().toLocaleLowerCase('id-ID');if(query.length<2){matches=[];results.innerHTML='<div class="al-account-hint">Ketik minimal 2 karakter untuk mencari rekening.</div>';results.hidden=false;return;}matches=accounts.filter(account=>(!postingOnly||account.is_posting)&&(`${account.account_code} ${account.account_name}`).toLocaleLowerCase('id-ID').includes(query)).slice(0,10);active=matches.length?0:-1;results.innerHTML=matches.length?matches.map((account,index)=>`<button type="button" class="al-account-result ${index===active?'active':''}" data-account-result="${esc(account.account_code)}"><b>${esc(account.account_code)}</b><span>${esc(account.account_name)}</span></button>`).join(''):'<div class="al-account-hint">Rekening tidak ditemukan.</div>';results.hidden=false;};
  search.onfocus=draw;search.oninput=()=>{hidden.value='';clear.hidden=true;draw();};search.onkeydown=event=>{if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();if(matches.length){active=(active+(event.key==='ArrowDown'?1:-1)+matches.length)%matches.length;qa('[data-account-result]',results).forEach((button,index)=>button.classList.toggle('active',index===active));}}else if(event.key==='Enter'&&matches[active]){event.preventDefault();choose(matches[active]);}else if(event.key==='Escape')results.hidden=true;};results.onmousedown=event=>{const button=event.target.closest('[data-account-result]'),account=button&&matches.find(item=>item.account_code===button.dataset.accountResult);if(account){event.preventDefault();choose(account);}};clear.onclick=()=>{hidden.value='';search.value='';clear.hidden=true;search.focus();draw();};
};
/* Rekening baru selalu mendapatkan kode anak dari induk yang dipilih.
   Handler dipasang sebelum picker diaktifkan agar event pilihan pertama tidak terlewat. */
accountModal=async function(account=null){
  const parentLabel=account?.parent_code?accountPickerLabel(accounts.find(item=>item.account_code===account.parent_code)):'—';
  const parentField=account
    ?`<label class="wide">Rekening induk<input value="${esc(parentLabel)}" readonly><input type="hidden" name="parent_code" value="${esc(account.parent_code||'')}"></label>`
    :`<label class="wide">Rekening induk${accountSearchField('parent_code','',false)}<small data-parent-code-note>Pilih induk untuk membuat kode anak otomatis.</small></label>`;
  const el=modal(`<h2>${account?'Edit Rekening':'Tambah Rekening'}</h2><p class="al-sub">${account?'Kode dan induk rekening tidak dapat diubah demi menjaga jurnal.':'Pilih rekening induk; kode anak berikutnya dibuat otomatis.'}</p><form data-account-form><div class="al-form-grid">${parentField}<label>Kode rekening<input required name="account_code" readonly value="${esc(account?.account_code||'')}" placeholder="Pilih rekening induk terlebih dahulu"><small>Kode mengikuti jalur rekening induk dan nomor anak berikutnya.</small></label><label>Nama rekening<input required name="account_name" value="${esc(account?.account_name||'')}"></label><label>Kelompok<select name="account_type">${['Neraca','Laba-Rugi','HPP'].map(value=>`<option value="${value}" ${account?.account_type===value?'selected':''}>${value}</option>`).join('')}</select></label><label><input type="checkbox" name="is_posting" ${account?.is_posting!==0?'checked':''}> Boleh diposting</label></div><div class="al-modal-foot"><button class="al-btn" type="button" data-close>Batal</button><button class="al-btn primary">Simpan</button></div></form>`);
  const form=q('[data-account-form]',el),code=q('[name="account_code"]',form),type=q('[name="account_type"]',form),note=q('[data-parent-code-note]',form);
  if(!account){
    const parent=q('[name="parent_code"]',form),picker=q('[data-named-account-picker]',form),search=q('[data-account-search]',picker);
    let requestId=0;
    const populateSuggestedCode=async()=>{
      const parentCode=String(parent.value||'').trim();
      const currentRequest=++requestId;
      if(!parentCode){code.value='';if(note){note.textContent='Pilih induk untuk membuat kode anak otomatis.';note.className='';}return;}
      code.value='';code.placeholder='Membuat kode otomatis…';
      try{
        const suggestion=await api('/api/accounting-lite/accounts/next-code?parent_code='+encodeURIComponent(parentCode));
        if(currentRequest!==requestId||parent.value!==parentCode)return;
        code.value=suggestion.account_code;
        type.value=suggestion.account_type;
        code.setCustomValidity('');
        if(note){note.textContent='Kode berikutnya dibuat otomatis dari rekening induk.';note.className='';}
      }catch(error){
        if(currentRequest!==requestId)return;
        code.value='';code.setCustomValidity(error.message);
        if(note){note.textContent=error.message;note.className='al-form-error';}
      }
    };
    parent.addEventListener('change',populateSuggestedCode);
    search?.addEventListener('input',()=>{if(!parent.value)populateSuggestedCode();});
    wireNamedAccountPicker(picker);
    // Menangani nilai yang dipulihkan browser atau picker yang sudah memiliki induk saat modal dibuat.
    queueMicrotask(populateSuggestedCode);
  }
  form.onsubmit=async event=>{event.preventDefault();const values=new FormData(form),data=Object.fromEntries(values);if(account)data.parent_code=account.parent_code||'';data.is_posting=values.get('is_posting')?1:0;try{await api(account?`/api/accounting-lite/accounts/${encodeURIComponent(account.account_code)}`:'/api/accounting-lite/accounts',{method:account?'PATCH':'POST',body:JSON.stringify(data)});el.remove();await load();}catch(error){alert(error.message);}};
};
