// Lapisan Buku Besar harus tetap dalam urutan: topbar → filter → judul/mode
// → kepala tabel. Wrapper ini berjalan setelah laporan selesai dirender agar
// offset memakai tinggi filter yang nyata, bukan tinggi tab yang telah lewat.
const ledgerViewWithCorrectStickyLayers=ledgerView;
ledgerView=async function(){
  const result=await ledgerViewWithCorrectStickyLayers();
  const root=q('.accounting-lite'),content=q('#alContent');
  if(!root||!content)return result;
  const topbar=q('.app-topbar'),toolbar=q('.al-toolbar',content);
  const topbarHeight=Math.ceil(topbar?.getBoundingClientRect().height||64);
  const toolbarHeight=Math.ceil(toolbar?.getBoundingClientRect().height||0);
  root.style.setProperty('--al-toolbar-top',`${topbarHeight}px`);
  root.style.setProperty('--al-table-head-top',`${topbarHeight+toolbarHeight}px`);
  const host=q('[data-ledger-report]',content);
  q('.al-actions',host)?.classList.add('al-ledger-heading');
  q('table.al-table',host)?.classList.add('al-ledger-table');
  q('.al-grid > aside.al-card',content)?.classList.add('al-ledger-account-panel');
  syncAccountingLedgerStickyLayers();
  setupLedgerFloatingHeader();
  return result;
};

// Semua elemen terkunci Buku Besar dihitung terhadap topbar aplikasi yang
// sebenarnya.  Jangan memakai tinggi tab: tab ikut menggulir sehingga offset
// lama membuat judul dan header tabel tertutup filter periode.
function syncAccountingLedgerStickyLayers(){
  if(!q('#accounting-sticky-layer-override')){
    const style=document.createElement('style');
    style.id='accounting-sticky-layer-override';
    style.textContent='.accounting-lite .al-tabs{margin-bottom:0!important;background:#f5f7fb!important}.accounting-lite .al-toolbar{top:var(--al-toolbar-top,64px)!important;margin-bottom:0!important;background:#f5f7fb!important;border-bottom:1px solid #dfe5ef}.accounting-lite .al-table thead th{position:static!important;top:auto!important;background:#f6f8fb;box-shadow:0 1px 0 #dfe5ef}.accounting-lite .al-management-list .al-table thead th{top:0!important;z-index:3}.accounting-lite .al-management-list tr.selected{background:#e9f6ff;color:#0868a9}';
    document.head.append(style);
  }
  const root=q('.accounting-lite');
  if(!root)return;
  const topbar=q('.app-topbar');
  const toolbar=q('.al-toolbar',root);
  const topbarHeight=Math.ceil(topbar?.getBoundingClientRect().height||64);
  const toolbarHeight=Math.ceil(toolbar?.getBoundingClientRect().height||0);
  root.style.setProperty('--al-toolbar-top',`${topbarHeight}px`);
  root.style.setProperty('--al-table-head-top',`${topbarHeight+toolbarHeight}px`);
  const heading=q('.al-ledger-heading',root);
  root.style.setProperty('--al-ledger-heading-height',`${Math.ceil(heading?.getBoundingClientRect().height||0)}px`);

  // syncStickyLayers versi lama memasang sticky per-<th>. Pada Buku Besar
  // hanya satu kepala tabel yang dikunci, agar tidak saling menimpa.
  const override=q('#accounting-sticky-layer-override');
  if(override&&!override.dataset.ledgerLayerFixed){
    override.dataset.ledgerLayerFixed='1';
    override.textContent+=' .accounting-lite .al-table thead th{position:static!important;top:auto!important}.accounting-lite .al-ledger-heading{position:static!important;top:auto!important}.accounting-lite .al-ledger-table thead,.accounting-lite .al-ledger-table thead th{position:static!important;top:auto!important;z-index:auto!important;background:#f6f8fb!important}';
  }
  ledgerFloatingHeaderRefresh();
}

// Chrome tidak stabil bila <thead> pada tabel laporan tinggi dibuat sticky.
// Salinan header biasa diposisikan fixed hanya ketika kepala tabel asli sudah
// melewati filter periode, sehingga data tidak tersela atau terlihat ganda.
let ledgerFloatingHeaderRefresh=()=>{};
function setupLedgerFloatingHeader(){
  document.getElementById('al-ledger-floating-header')?.remove();
  const root=q('.accounting-lite'),table=q('table.al-ledger-table',root),thead=q('thead',table),toolbar=q('.al-toolbar',root);
  if(!root||!table||!thead||!toolbar){ledgerFloatingHeaderRefresh=()=>{};return;}
  const floating=document.createElement('div');
  floating.id='al-ledger-floating-header';
  floating.className='al-ledger-floating-header';
  const headers=[...thead.querySelectorAll('th')];
  floating.innerHTML=headers.map(th=>'<span class="'+(th.classList.contains('number')?'number':'')+'">'+esc(th.textContent.trim())+'</span>').join('');
  document.body.append(floating);
  const update=()=>{
    if(!document.body.contains(table)){floating.remove();return;}
    const toolbarRect=toolbar.getBoundingClientRect(),tableRect=table.getBoundingClientRect(),headerRect=thead.getBoundingClientRect(),cells=[...thead.querySelectorAll('th')];
    const top=Math.round(toolbarRect.bottom);
    floating.style.left=Math.round(tableRect.left)+'px';
    floating.style.top=top+'px';
    floating.style.width=Math.round(tableRect.width)+'px';
    floating.style.gridTemplateColumns=cells.map(cell=>Math.round(cell.getBoundingClientRect().width)+'px').join(' ');
    floating.classList.toggle('is-visible',headerRect.top<top&&tableRect.bottom>top+Math.max(32,headerRect.height));
  };
  ledgerFloatingHeaderRefresh=update;
  requestAnimationFrame(update);
}

// Semua laporan selain Buku Besar memakai satu salinan kepala tabel aktif.
// Ini menghindari beberapa <thead> sticky bertumpuk pada laporan yang terdiri
// dari banyak kelompok, sambil tetap menjaga nama kolom terlihat saat menggulir.
let reportFloatingHeaderRefresh=()=>{};
function setupReportFloatingHeader(){
  document.getElementById('al-report-floating-header')?.remove();
  const root=q('.accounting-lite'),content=q('#alContent'),toolbar=q('.al-toolbar',content);
  if(!root||!content||!toolbar){reportFloatingHeaderRefresh=()=>{};return;}
  const floating=document.createElement('div');
  floating.id='al-report-floating-header';
  floating.className='al-report-floating-header';
  document.body.append(floating);
  let activeTable=null;
  const update=()=>{
    if(!document.body.contains(content)){floating.remove();return;}
    if(innerWidth<=800){floating.classList.remove('is-visible');return;}
    const top=Math.round(toolbar.getBoundingClientRect().bottom);
    const candidates=qa('table.al-table:not(.al-ledger-table)',content).map(table=>({table,head:q('thead',table),rect:table.getBoundingClientRect()})).filter(item=>item.head&&item.head.getBoundingClientRect().top<top&&item.rect.bottom>top+Math.max(32,item.head.getBoundingClientRect().height)).sort((left,right)=>right.head.getBoundingClientRect().top-left.head.getBoundingClientRect().top);
    const active=candidates[0];
    if(!active){floating.classList.remove('is-visible');return;}
    const head=active.head,cells=qa('th',head),rect=active.rect;
    if(activeTable!==active.table){floating.innerHTML=cells.map(cell=>'<span class="'+(cell.classList.contains('number')?'number':'')+'">'+esc(cell.textContent.trim())+'</span>').join('');activeTable=active.table;}
    floating.style.left=Math.round(rect.left)+'px';
    floating.style.top=top+'px';
    floating.style.width=Math.round(rect.width)+'px';
    floating.style.gridTemplateColumns=cells.map(cell=>Math.round(cell.getBoundingClientRect().width)+'px').join(' ');
    floating.classList.add('is-visible');
  };
  reportFloatingHeaderRefresh=update;
  requestAnimationFrame(update);
}
