hppView=async function(){const content=reportShell('HPP');wirePeriodFilters(content,hppView);try{const d=await api('/api/accounting-lite/hpp?start='+encodeURIComponent(start)+'&end='+encodeURIComponent(end)),sections=d.rows||[],total=d.totals||{};if(!document.getElementById('al-hpp-statement-style')){const style=document.createElement('style');style.id='al-hpp-statement-style';style.textContent='.al-hpp-section td{font-weight:800;background:#f3f7fc;border-top:1px solid #cbd7e6}.al-hpp-section .number{font-weight:800}.al-hpp-total td{font-weight:800;background:#eaf3ff;border-top:2px solid #9fb4ca}.al-hpp-unmapped td{background:#fff8e7}';document.head.appendChild(style);}let number=0;const body=sections.map(section=>{const subtotal=key=>(section.rows||[]).reduce((sum,row)=>sum+Number(row[key]||0),0),warning=section.unmapped?' al-hpp-unmapped':'';return '<tr class="al-hpp-section'+warning+'"><td colspan="3">'+esc(section.label)+'</td><td class="number">'+money(subtotal('previous'))+'</td><td class="number">'+money(subtotal('current'))+'</td><td class="number">'+money(subtotal('ytd'))+'</td></tr>'+((section.rows||[]).map(row=>'<tr'+warning+'><td>'+esc(++number)+'</td><td>'+esc(row.account_code||'—')+'</td><td>'+esc(row.account_name)+'</td><td class="number">'+money(row.previous)+'</td><td class="number">'+money(row.current)+'</td><td class="number">'+money(row.ytd)+'</td></tr>').join(''));}).join('');content.querySelector('.al-card').innerHTML='<div class="al-actions" style="justify-content:space-between"><h2 class="al-section-title">Harga Pokok Penjualan</h2><button class="al-btn" type="button" data-hpp-mapping>⚙ Pengaturan rekening HPP</button></div><div class="al-note">Persediaan awal Januari berasal dari jurnal SA agregat; bulan berikutnya memakai stok akhir bulan sebelumnya. HPP = persediaan awal + pembelian − persediaan akhir.</div><div class="al-table-wrap"><table class="al-table"><thead><tr><th>NO</th><th>NO AKUN</th><th>URAIAN</th><th class="number">S.D BULAN LALU</th><th class="number">BULAN INI</th><th class="number">S.D BULAN INI</th></tr></thead><tbody>'+body+'<tr class="al-hpp-total"><td colspan="3">HARGA POKOK PENJUALAN</td><td class="number">'+money(total.previous)+'</td><td class="number">'+money(total.current)+'</td><td class="number">'+money(total.ytd)+'</td></tr></tbody></table></div>';q('[data-hpp-mapping]',content).onclick=()=>reportMappingSettingsModal('hpp');}catch(error){content.innerHTML='<div class="al-empty">'+esc(error.message)+'</div>';}};

