const reportMappingSettingsModalWithSpecialLines=reportMappingSettingsModal;
reportMappingSettingsModal=async function(reportKind){
  const result=await reportMappingSettingsModalWithSpecialLines(reportKind);
  if(!['income','balance'].includes(reportKind))return result;
  setTimeout(()=>{
    const modalNode=qa('.al-modal').at(-1),form=q('[data-report-mapping-form]',modalNode);
    if(!form||form.dataset.specialLinesReady)return;
    form.dataset.specialLinesReady='1';
    api('/api/accounting-lite/report-mappings?report_kind='+encodeURIComponent(reportKind)).then(data=>{
      const lines=(data.special_lines||[]),sections=[...new Set([...(data.default_sections||[]),...(data.mappings||[]).map(row=>row.section_name),...lines.map(row=>row.section_name)])],sourceLabel={hpp_report:'Hasil Laporan HPP',period_profit:'Hasil Laba/Rugi periode'},panel=document.createElement('section');
      panel.className='al-balance-section';
      panel.innerHTML='<h3>Baris hasil khusus</h3><p class="al-sub">Baris ini tidak memakai nomor rekening. Saldo rekening yang dipetakan tetap ditampilkan apa adanya untuk pencocokan Buku Besar.</p>'+(lines.map(line=>'<div class="al-form-grid" data-special-line data-special-source="'+esc(line.source_kind)+'"><label>Sumber nilai<input value="'+esc(sourceLabel[line.source_kind]||line.source_kind)+'" disabled></label><label>Nama pada laporan<input data-special-label value="'+esc(line.label)+'"></label><label>Kelompok<select data-special-section>'+sections.map(section=>'<option value="'+esc(section)+'" '+(section===line.section_name?'selected':'')+'>'+esc(section)+'</option>').join('')+'</select></label><label>Urutan<input data-special-order type="number" min="0" value="'+esc(line.sort_order)+'"></label><label style="display:flex;align-items:center;gap:8px;margin-top:20px"><input data-special-enabled type="checkbox" '+(line.enabled?'checked':'')+'> Tampilkan</label></div>').join(''));
      const footer=q('.al-modal-foot',form);footer?.insertAdjacentElement('beforebegin',panel);
      const originalSubmit=form.onsubmit;
      form.onsubmit=async event=>{event.preventDefault();
        const special_lines=qa('[data-special-line]',panel).map(row=>({source_kind:row.dataset.specialSource,label:q('[data-special-label]',row).value,section_name:q('[data-special-section]',row).value,sort_order:Number(q('[data-special-order]',row).value||0),enabled:q('[data-special-enabled]',row).checked}));
        try{await api('/api/accounting-lite/report-mappings?report_kind='+encodeURIComponent(reportKind),{method:'PUT',body:JSON.stringify({special_only:true,special_lines})});return originalSubmit.call(form,event);}catch(error){alert(error.message);}
      };
    }).catch(error=>alert(error.message));
  },0);
  return result;
};
// Pemetaan laporan disimpan secara batch agar pengaturan kelompok tetap
// konsisten. Penanda ini menjelaskan bahwa perubahan baru dihitung setelah
// pengguna menyimpan pemetaan.
const reportMappingSettingsModalWithSaveStatus=reportMappingSettingsModal;
reportMappingSettingsModal=async function(reportKind){
  const result=await reportMappingSettingsModalWithSaveStatus(reportKind);
  if(!['income','balance'].includes(reportKind))return result;
  setTimeout(()=>{
    const modalNode=qa('.al-modal').at(-1),form=q('[data-report-mapping-form]',modalNode);
    if(!form||form.dataset.mappingSaveStatusReady)return;
    form.dataset.mappingSaveStatusReady='1';
    const groups=q('[data-map-groups]',form),saveState=document.createElement('div'),saveNow=document.createElement('button');
    saveState.className='al-note';
    saveState.dataset.mapSaveState='1';
    saveState.textContent='Belum ada perubahan. Pemetaan tersimpan langsung dipakai untuk menghitung ulang laporan.';
    saveNow.type='button';
    saveNow.className='al-btn primary';
    saveNow.dataset.mapSaveNow='1';
    saveNow.textContent='Simpan pemetaan';
    const actions=document.createElement('div');
    actions.className='al-actions';
    actions.style.margin='10px 0';
    actions.append(saveNow);
    groups?.before(saveState,actions);
    let dirty=false;
    const setDirty=()=>{
      dirty=true;
      saveState.textContent='Ada perubahan pemetaan yang belum disimpan. Tekan “Simpan pemetaan” agar total laporan dihitung ulang.';
      saveNow.textContent='Simpan pemetaan sekarang';
    };
    saveNow.onclick=()=>form.requestSubmit();
    form.addEventListener('click',event=>{
      const button=event.target.closest('[data-map-add-account],[data-map-add-section],[data-map-remove],[data-map-delete-section]');
      if(!button)return;
      const accountWasSelected=Boolean(q('[data-new-account-code]',form)?.value);
      setTimeout(()=>{
        if(button.matches('[data-map-add-account]')&&!accountWasSelected)return;
        setDirty();
        const selectedSection=q('[data-new-section]',form)?.value;
        if(selectedSection){
          const detail=[...qa('details',groups)].find(item=>item.querySelector('summary')?.textContent.includes(selectedSection));
          if(detail)detail.open=true;
        }
      },0);
    },true);
    form.addEventListener('submit',()=>{
      saveNow.disabled=true;
      saveNow.textContent='Menyimpan…';
    },true);
  },0);
  return result;
};
/* Invoicing: invoice historis hanya menautkan jurnal yang sudah ada; invoice baru diposting setelah pengguna meninjau draf. */
let invoiceUiFilters={start:'',end:'',status:''};
function invoiceFmtDate(value){return value||new Date().toISOString().slice(0,10);}
function invoiceDueDateString(value,days=30){const parsed=new Date(`${value}T00:00:00Z`);if(Number.isNaN(parsed.getTime()))return '';parsed.setUTCDate(parsed.getUTCDate()+Math.max(0,Math.min(720,Number(days)||0)));return parsed.toISOString().slice(0,10);}
function invoicePrintMoney(value){const amount=Number(value||0),digits=Number.isInteger(amount)?0:2;return 'Rp '+amount.toLocaleString('id-ID',{minimumFractionDigits:digits,maximumFractionDigits:2});}
function invoiceTabAllowed(){return accountingPermission('accounting_lite')||accountingPermission('accounting_reports');}
function invoiceItemOptions(items,selected=''){return '<option value="">Pilih barang…</option>'+items.filter(item=>item.ready).map(item=>'<option value="'+esc(item.item_code)+'" '+(item.item_code===selected?'selected':'')+'>'+esc(item.item_code)+' — '+esc(item.item_name)+'</option>').join('');}
let invoicePickerItems=[];function invoiceItemSearchField(items,value=''){invoicePickerItems=items;const item=items.find(row=>row.item_code===value),label=item?item.item_code+' — '+item.item_name:'';return '<div class="al-account-picker" data-invoice-item-picker><input type="hidden" data-invoice-item value="'+esc(value)+'"><div class="al-account-picker-control"><input type="search" data-invoice-item-search autocomplete="off" value="'+esc(label)+'" placeholder="Cari kode atau nama barang" aria-label="Cari barang"><button type="button" class="al-account-clear" data-invoice-item-clear '+(label?'':'hidden')+'>×</button></div><div class="al-account-results" data-invoice-item-results hidden></div></div>';}
function wireInvoiceItemPicker(wrapper){if(!wrapper||wrapper.dataset.wired)return;wrapper.dataset.wired='1';const hidden=q('[data-invoice-item]',wrapper),search=q('[data-invoice-item-search]',wrapper),results=q('[data-invoice-item-results]',wrapper),clear=q('[data-invoice-item-clear]',wrapper);let matches=[];const choose=item=>{hidden.value=item.item_code;search.value=item.item_code+' — '+item.item_name;clear.hidden=false;results.hidden=true;hidden.dispatchEvent(new Event('change',{bubbles:true}));};const draw=()=>{const text=search.value.trim().toLocaleLowerCase('id-ID');if(text.length<2){results.innerHTML='<div class="al-account-hint">Ketik minimal 2 karakter untuk mencari barang.</div>';results.hidden=false;return;}matches=invoicePickerItems.filter(item=>(item.item_code+' '+item.item_name).toLocaleLowerCase('id-ID').includes(text)).slice(0,10);results.innerHTML=matches.length?matches.map(item=>'<button type="button" class="al-account-result" data-invoice-item-result="'+esc(item.item_code)+'"><b>'+esc(item.item_code)+'</b><span>'+esc(item.item_name)+'</span></button>').join(''):'<div class="al-account-hint">Barang tidak ditemukan.</div>';results.hidden=false;};search.onfocus=()=>{if(hidden.value)search.select();else draw();};search.oninput=()=>{hidden.value='';clear.hidden=true;draw();};results.onmousedown=event=>{const button=event.target.closest('[data-invoice-item-result]'),item=button&&matches.find(row=>row.item_code===button.dataset.invoiceItemResult);if(item){event.preventDefault();choose(item);}};clear.onclick=()=>{hidden.value='';search.value='';clear.hidden=true;search.focus();draw();};}
function invoiceLineMarkup(items,line={}){return '<div class="al-invoice-line" data-invoice-line><label class="al-invoice-item-field">Barang'+invoiceItemSearchField(items,line.item_code||'')+'</label><label>Jumlah<input required data-invoice-qty type="number" min="0.0001" step="any" value="'+esc(line.quantity||1)+'"></label><label>Harga satuan<input required data-invoice-price inputmode="decimal" value="'+esc(line.unit_price||'')+'"></label><label>Potongan harga<input data-invoice-discount inputmode="decimal" value="'+esc(line.discount_amount||'0')+'"></label><label>Nilai bersih<output data-invoice-line-total>Rp0</output></label><button type="button" class="al-btn danger" data-remove-invoice-line aria-label="Hapus barang">×</button></div>';}
function invoiceReadLines(form,itemMap){return qa('[data-invoice-line]',form).map(row=>{const code=q('[data-invoice-item]',row).value,item=itemMap.get(code),quantity=Number(q('[data-invoice-qty]',row).value||0),unitPrice=rupiahNumber(q('[data-invoice-price]',row).value),discount=rupiahNumber(q('[data-invoice-discount]',row).value);return {item_code:code,item_name:item?.item_name||'',quantity,unit_price:unitPrice,discount_amount:discount};});}
