  const panel=q('.al-ledger-account-panel',content);if(panel&&!q('[data-mobile-account-toggle]',panel)){const tree=q('.al-tree',panel),button=document.createElement('button');button.type='button';button.className='al-btn al-mobile-account-toggle';button.dataset.mobileAccountToggle='1';button.textContent='Pilih rekening';button.setAttribute('aria-expanded','false');tree?.before(button);const sync=()=>{const mobile=matchMedia('(max-width:800px)').matches;const collapsed=mobile&&alSession.get('accounting.ledgerPanel')!=='open';panel.classList.toggle('is-mobile-collapsed',collapsed);button.hidden=!mobile;button.setAttribute('aria-expanded',String(!collapsed));button.textContent=collapsed?'Pilih rekening':'Sembunyikan rekening';};button.onclick=()=>{const isOpen=panel.classList.contains('is-mobile-collapsed');panel.classList.toggle('is-mobile-collapsed',!isOpen);alSession.set('accounting.ledgerPanel',isOpen?'open':'closed');sync();};addEventListener('resize',sync,{passive:true});sync();}
