// Pilihan tampilan laporan: rekening yang belum dipetakan tetap dihitung dalam
// total, namun dapat disembunyikan dari semua laporan dan Dashboard LK.
// Disimpan di browser agar pilihan yang sama berlaku saat berpindah tab.
const accountingUnmappedVisibility={
  // Secara bawaan rincian belum dipetakan tidak ditampilkan. Nilainya tetap
  // dihitung oleh API; pengguna dapat membuka kembali rinciannya dari opsi ini.
  get hidden(){try{return localStorage.getItem('accounting.hideUnmappedReports')!=='0';}catch{return true;}},
  set hidden(value){try{localStorage.setItem('accounting.hideUnmappedReports',value?'1':'0');}catch{}}
};
function applyAccountingUnmappedVisibility(root=q('#alContent')){
  if(!root)return;
  const hidden=accountingUnmappedVisibility.hidden;
  // Tandai elemen saat dirender, tetapi tetap dukung laporan versi lama yang
  // hanya memiliki judul. `hidden` dan display dipakai bersama agar CSS tema
  // tidak dapat membuat bagian belum dipetakan muncul kembali.
  const setVisibility=element=>{
    if(!element)return;
    element.hidden=hidden;
    element.style.display=hidden?'none':'';
  };
  qa('[data-unmapped-report-section],.al-hpp-unmapped',root).forEach(setVisibility);
  qa('h3,h4',root).forEach(heading=>{
    if(!/belum\s+dipetakan/i.test(heading.textContent||''))return;
    setVisibility(heading.closest('[data-unmapped-report-section],.al-balance-section,.al-monthly-statement,.al-annual-section')||heading.parentElement);
  });
}
function addAccountingUnmappedToggle(root=q('#alContent')){
  if(!root)return;
  const target=q('.al-actions',root)||q('.al-card',root);
  if(!target)return;
  let control=q('[data-hide-unmapped-control]',root);
  if(!control){
    control=document.createElement('label');
    control.className='al-unmapped-toggle';
    control.dataset.hideUnmappedControl='1';
    control.innerHTML='<input type="checkbox" data-hide-unmapped> Sembunyikan rekening belum dipetakan';
    target.append(control);
    q('[data-hide-unmapped]',control).onchange=event=>{
      accountingUnmappedVisibility.hidden=event.currentTarget.checked;
      applyAccountingUnmappedVisibility(root);
    };
  }
  q('[data-hide-unmapped]',control).checked=accountingUnmappedVisibility.hidden;
  applyAccountingUnmappedVisibility(root);
}
