function wirePibSupplierPicker(wrapper,suppliers,onChoose=()=>{}){if(!wrapper||wrapper.dataset.wired)return;wrapper.dataset.wired='1';const search=q('[data-pib-supplier-search]',wrapper),hidden=q('[name="supplier_code"]',wrapper),results=q('[data-pib-supplier-results]',wrapper),clear=q('[data-pib-supplier-clear]',wrapper);let matches=[],active=-1;const label=item=>item?`${item.supplier_code} — ${item.supplier_name}`:'';const choose=item=>{hidden.value=item.supplier_code;search.value=label(item);results.hidden=true;results.innerHTML='';clear.hidden=false;onChoose(item);};const draw=()=>{const query=search.value.trim().toLocaleLowerCase('id-ID');if(query.length<2){matches=[];active=-1;results.innerHTML='<div class="al-account-hint">Ketik minimal 2 karakter untuk mencari supplier.</div>';results.hidden=false;return;}const seen=new Set();matches=suppliers.filter(item=>{const code=String(item.supplier_code||'');if(seen.has(code))return false;seen.add(code);return `${code} ${item.supplier_name||''}`.toLocaleLowerCase('id-ID').includes(query);}).sort((left,right)=>`${left.supplier_code} ${left.supplier_name}`.localeCompare(`${right.supplier_code} ${right.supplier_name}`,'id')).slice(0,10);active=matches.length?0:-1;results.innerHTML=matches.length?matches.map((item,index)=>`<button type="button" class="al-account-result ${index===active?'active':''}" data-pib-supplier-result="${esc(item.supplier_code)}"><b>${esc(item.supplier_code)}</b><span>${esc(item.supplier_name)}<small>${esc(pibSupplierPayableLabel(item))}</small></span></button>`).join(''):'<div class="al-account-hint">Supplier tidak ditemukan.</div>';results.hidden=false;};const highlight=()=>qa('[data-pib-supplier-result]',results).forEach((button,index)=>button.classList.toggle('active',index===active));search.onfocus=()=>hidden.value?search.select():draw();search.oninput=()=>{hidden.value='';clear.hidden=true;onChoose(null);draw();};search.onkeydown=event=>{if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();if(results.hidden)draw();if(matches.length){active=(active+(event.key==='ArrowDown'?1:-1)+matches.length)%matches.length;highlight();}}else if(event.key==='Enter'&&matches[active]){event.preventDefault();choose(matches[active]);}else if(event.key==='Escape')results.hidden=true;};results.onmousedown=event=>{const button=event.target.closest('[data-pib-supplier-result]'),item=button&&matches.find(candidate=>candidate.supplier_code===button.dataset.pibSupplierResult);if(item){event.preventDefault();choose(item);}};clear.onclick=()=>{hidden.value='';search.value='';clear.hidden=true;onChoose(null);search.focus();draw();};}
function pibLineMarkup(index,item=null){return `<div class="al-pib-line" data-pib-line="${index}"><label class="al-pib-item-field">Barang${itemPickerMarkup(item,`pib_item_${index}`)}</label><div class="al-pib-inputs"><label>Jumlah<input type="number" data-pib-quantity min="0.000001" step="any" value="1"></label><label>Satuan<input data-pib-unit maxlength="30" placeholder="PCS"></label><label>Harga/pcs<input type="number" data-pib-price min="0" step="any" value="0"></label><label>BM %<input type="number" data-pib-duty min="0" step="any" value="0"></label><label>PPnBM %<input type="number" data-pib-ppnbm min="0" step="any" value="0"></label></div><div class="al-pib-line-total"><small>Nilai impor</small><b data-pib-import>Rp0</b><small>Nilai persediaan BRM</small><b data-pib-landed>Rp0</b></div><button type="button" class="al-btn danger" data-remove-pib-line title="Hapus barang">×</button></div>`;}
