function pibJournalRows(journal){return (journal?.lines||[]).filter(row=>Number(row.debit||0)>0||Number(row.credit||0)>0).map(row=>`<tr><td><b>${esc(row.account_code)}</b> · ${esc(row.label)}</td><td class="number">${row.debit?money(row.debit):'—'}</td><td class="number">${row.credit?money(row.credit):'—'}</td></tr>`).join('');}
function pibReadOnlyJournal(title,journal){return journal?`<h3>${title}</h3><section class="al-pib-review-journal"><div class="al-pib-journal-meta"><b>${esc(journal.voucher_number)}</b><span>${esc(journal.description)}</span></div><table class="al-table"><thead><tr><th>Rekening / Uraian</th><th class="number">Debit</th><th class="number">Kredit</th></tr></thead><tbody>${pibJournalRows(journal)}</tbody><tfoot><tr><th>Total</th><th class="number">${money(journal.debit_total)}</th><th class="number">${money(journal.credit_total)}</th></tr><tr><td colspan="3" class="${journal.balanced?'al-pib-balanced':'al-pib-unbalanced'}">${journal.balanced?'✓ Jurnal seimbang':'⚠ Jurnal belum seimbang'}</td></tr></tfoot></table></section>`:'';}
function pibPrintHtml(preview){const pib=preview.pib,lines=pib.lines||[],importTotal=lines.reduce((sum,line)=>sum+Number(line.import_amount||0),0),inventoryTotal=lines.reduce((sum,line)=>sum+Number(line.landed_amount||0),0),paymentTotal=Number(pib.customs_duty_amount||0)+Number(pib.vat_amount||0)+Number(pib.pph22_amount||0),supplierTotal=importTotal+Number(pib.freight_amount||0),items=lines.map((line,index)=>`<tr><td>${index+1}</td><td><b>${esc(line.item_code)}</b><br>${esc(line.item_name)}</td><td class="right">${Number(line.quantity||0).toLocaleString('id-ID')} ${esc(line.unit_name||'')}</td><td class="right">${money(line.unit_price_foreign||0)} ${esc(line.currency_code||pib.currency_code||'')}</td><td class="right">${money(line.import_amount||0)}</td><td class="right">${money(line.landed_amount||0)}</td></tr>`).join('');return `<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Invoice PIB ${esc(pib.invoice_number||pib.aju_number)}</title><style>body{font-family:Arial,sans-serif;color:#14213d;margin:28px;font-size:12px}.doc{max-width:900px;margin:auto}.head{display:flex;justify-content:space-between;border-bottom:2px solid #173b6c;padding-bottom:12px}.head h1{font-size:20px;margin:0 0 6px}.muted{color:#56657b}.meta{display:grid;grid-template-columns:repeat(2,1fr);gap:8px 36px;margin:18px 0}.meta div{padding:7px 0;border-bottom:1px solid #dce3ed}.meta b{display:block;font-size:10px;color:#50617c;text-transform:uppercase;margin-bottom:3px}table{border-collapse:collapse;width:100%;margin-top:16px}th,td{border:1px solid #cdd8e6;padding:8px;vertical-align:top}th{background:#edf3fa;font-size:10px;text-transform:uppercase}.right{text-align:right}.summary{width:380px;margin:18px 0 0 auto}.summary td{border-width:0 0 1px}.summary .total td{font-weight:700;background:#edf3fa;border-top:2px solid #173b6c}.foot{margin-top:26px;border-top:1px solid #dce3ed;padding-top:10px;color:#56657b}@media print{body{margin:12mm}.no-print{display:none}}</style></head><body><main class="doc"><header class="head"><div><h1>INVOICE IMPOR / CEK LIST PIB</h1><div class="muted">Dokumen informasi transaksi impor yang telah diposting</div></div><div class="right"><b>No. Invoice</b><br>${esc(pib.invoice_number||'—')}</div></header><section class="meta"><div><b>No. AJU</b>${esc(pib.aju_number)}</div><div><b>Tanggal PIB</b>${date(pib.transaction_date)}</div><div><b>Supplier</b>${esc(pib.supplier_code||'—')}</div><div><b>Rekening Hutang</b>${esc(pib.supplier_payable_account_code||'—')}</div><div><b>Mata Uang / Kurs</b>${esc(pib.currency_code||'—')} / ${Number(pib.exchange_rate||0).toLocaleString('id-ID')}</div><div><b>Status</b>Diposting</div></section><table><thead><tr><th>No.</th><th>Barang</th><th class="right">Jumlah</th><th class="right">Harga/pcs</th><th class="right">Nilai Impor</th><th class="right">Nilai Stok BRM</th></tr></thead><tbody>${items||'<tr><td colspan="6">Tidak ada rincian barang.</td></tr>'}</tbody></table><table class="summary"><tbody><tr><td>Nilai impor</td><td class="right">${money(importTotal)}</td></tr><tr><td>Freight</td><td class="right">${money(pib.freight_amount||0)}</td></tr><tr><td>Nilai hutang supplier (HI)</td><td class="right">${money(supplierTotal)}</td></tr><tr><td>Bea masuk</td><td class="right">${money(pib.customs_duty_amount||0)}</td></tr><tr><td>PPN impor</td><td class="right">${money(pib.vat_amount||0)}</td></tr><tr><td>PPh 22</td><td class="right">${money(pib.pph22_amount||0)}</td></tr><tr><td>Total pembayaran PIB</td><td class="right">${money(paymentTotal)}</td></tr><tr class="total"><td>Nilai persediaan BRM</td><td class="right">${money(inventoryTotal)}</td></tr></tbody></table><footer class="foot">Referensi jurnal: BRM ${esc(preview.brm?.voucher_number||'—')} · HI ${esc(preview.invoice?.voucher_number||'—')} · PIB ${esc(preview.payment?.voucher_number||'—')}<br>Dokumen ini hanya-baca; koreksi transaksi dilakukan melalui jurnal koreksi.</footer></main></body></html>`;}
function pibPrintInvoice(preview){const printed=window.open('','_blank');if(!printed){alert('Jendela cetak diblokir oleh browser. Izinkan pop-up lalu coba lagi.');return;}printed.document.open();printed.document.write(pibPrintHtml(preview));printed.document.close();printed.focus();setTimeout(()=>printed.print(),120);}
