    qa('[data-print-posted-pib]',card).forEach(button=>button.onclick=async()=>{const printWindow=window.open('','_blank');if(!printWindow){alert('Jendela cetak diblokir oleh browser. Izinkan pop-up lalu coba lagi.');return;}button.disabled=true;try{printWindow.document.write('<title>Menyiapkan Invoice PIB…</title>');const preview=await api(`/api/accounting-lite/pib/${button.dataset.printPostedPib}`);printWindow.document.open();printWindow.document.write(pibPrintHtml(preview));printWindow.document.close();printWindow.focus();setTimeout(()=>printWindow.print(),120);}catch(error){printWindow.close();alert(error.message);}finally{button.disabled=false;}});
